use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    let n = board.len();
    var i = 0;
    while i < n {
        if i > 0 {
            io.write(text: ";")?;
        }
        let dish = board.get(index: i);
        galley.kitchen.serve(dish)?;
        i = i + 1;
    }
    return Ok(unit);
}

