use mill.stock;
use mill.rules;

fn lines() -> String {
    var result = "";
    var first = true;
    for plank in stock.planks() {
        if rules.keep(plank) {
            let label = rules.label(plank);
            if first {
                result = label;
                first = false;
            } else {
                result = result.concat(other: ",").concat(other: label);
