use harbor.signal;

fn entries() -> String {
    var result = "";
    var first = true;
    for s in harbor.signal.signals() {
        let rendered = match s {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(density) => "fog:".concat(other: density),
        };
        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(other: ";").concat(other: rendered);
        }
    }
    result
}

use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    for frame in relay.feed.frames() {
        let val = match relay.feed.decode(frame) {
            Ok(v) => v,
            Err(_) => 0,
        };
        total = total + val;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

